<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { Refresh, Plus } from '@element-plus/icons-vue'
import PageHeader from '../components/PageHeader.vue'
import AlertSample from '../components/AlertSample.vue'
import AlertCommands from '../components/AlertCommands.vue'
import AlertRuleEditor from '../components/AlertRuleEditor.vue'
import { errorText } from '../api'
import { session } from '../session'
import { alertCommand, alertEventLabels, alertFreshnessLabels, alertID, alertKindLabels, alertKinds, alertQuery, alertRole, parseAlertCapabilities, parseAlertEnvelope, parseAlertEpisode, parseAlertEvent, parseAlertPage, parseAlertRule } from '../alerts'
import type { AlertCapabilities, AlertEpisode, AlertEvent, AlertFreshness, AlertRule } from '../alerts'
import { alertContext, alertRejectionLabels, alertsJournal, createAlertEpoch, createAlertPager, submitAlertCommand } from '../alerts-state'
import { alertsRequest } from '../alerts-transport'

const context=computed(()=>alertContext(session.me?.user.id,session.me?.tenant?.id,session.me?.user.platform_role||'',session.me?.csrf_token||'',session.mfaPending,session.enrollmentRequired)),allowed=computed(()=>alertRole(session.me?.user.platform_role||'')),admin=computed(()=>session.me?.user.platform_role==='admin'),tab=ref('current'),currentStatus=ref('open'),episodeKind=ref(''),episodeRule=ref(''),ruleState=ref(''),ruleKind=ref(''),ruleScope=ref('')
const capGate=createAlertEpoch(),detailGate=createAlertEpoch(),ackGate=createAlertEpoch(),rulePager=createAlertPager<AlertRule>(),episodePager=createAlertPager<AlertEpisode>(),eventPager=createAlertPager<AlertEvent>()
const capabilities=ref<AlertCapabilities|null>(null),capLoading=ref(false),capError=ref(''),rules=ref(rulePager.snapshot()),episodes=ref(episodePager.snapshot()),events=ref(eventPager.snapshot()),selectedRule=ref<AlertRule|null>(null),selectedEpisode=ref<AlertEpisode|null>(null),detailLoading=ref(false),detailError=ref(''),ackBusy=ref(false),ackError=ref(''),ackMessage=ref(''),editorOpen=ref(false),editingRule=ref<AlertRule|null>(null),commandRefresh=ref(0)
const viewContext=computed(()=>JSON.stringify([context.value,tab.value,currentStatus.value,episodeKind.value,episodeRule.value,ruleState.value,ruleKind.value,ruleScope.value]))
const canWrite=computed(()=>allowed.value&&capabilities.value!==null&&!capabilities.value.recovery_mode&&!session.mfaPending&&!session.enrollmentRequired)
const ackBlocked=computed(()=>{void commandRefresh.value;if(!selectedEpisode.value||!session.me)return true;try{return alertsJournal.blocked(session.me.user.id,`episode:${selectedEpisode.value.id}`)}catch{return true}})
function tone(f:AlertFreshness):'warning'|'info'|'success'{return f==='fresh'?'success':['stale','never_evaluated'].includes(f)?'warning':'info'}
function stateLabel(value:string){return ({enabled:'启用',disabled:'停用',retired:'已退役',open:'待共同确认',acknowledged:'已共同确认',resolved:'已结束'} as Record<string,string>)[value]||value}
function resetDetails(){detailGate.reset(context.value);ackGate.reset(context.value);eventPager.reset(context.value);selectedRule.value=null;selectedEpisode.value=null;detailLoading.value=false;detailError.value='';ackBusy.value=false;ackError.value='';ackMessage.value='';events.value=eventPager.snapshot()}
async function loadCapabilities(){if(!allowed.value)return;const ticket=capGate.ticket();capLoading.value=true;capError.value='';try{const raw=await alertsRequest('/platform/alerts/capabilities',{current:()=>capGate.accepts(ticket)});if(capGate.accepts(ticket))capabilities.value=parseAlertEnvelope(raw,parseAlertCapabilities)}catch(cause){if(capGate.accepts(ticket)){capError.value=errorText(cause);capabilities.value=null}}finally{if(capGate.accepts(ticket))capLoading.value=false}}
async function loadRules(first=true){if(!allowed.value)return;const ticket=rulePager.begin(first);if(!ticket)return;rules.value=rulePager.snapshot();try{const path=alertQuery('rules',{state:ruleState.value,kind:ruleKind.value,scope_id:ruleScope.value},ticket.cursor),raw=await alertsRequest(path,{current:()=>rulePager.accepts(ticket)});if(rulePager.accepts(ticket))rulePager.accept(ticket,parseAlertPage(raw,parseAlertRule,r=>r.id))}catch(cause){rulePager.fail(ticket,cause)}finally{if(rulePager.accepts(ticket))rules.value=rulePager.snapshot()}}
async function loadEpisodes(first=true){if(!allowed.value)return;const ticket=episodePager.begin(first);if(!ticket)return;episodes.value=episodePager.snapshot();try{const path=alertQuery('episodes',{status:tab.value==='history'?'resolved':currentStatus.value,kind:episodeKind.value,rule_id:episodeRule.value},ticket.cursor),raw=await alertsRequest(path,{current:()=>episodePager.accepts(ticket)});if(episodePager.accepts(ticket))episodePager.accept(ticket,parseAlertPage(raw,parseAlertEpisode,r=>r.id))}catch(cause){episodePager.fail(ticket,cause)}finally{if(episodePager.accepts(ticket))episodes.value=episodePager.snapshot()}}
async function loadEvents(first=true){const episode=selectedEpisode.value;if(!episode)return;const ticket=eventPager.begin(first);if(!ticket)return;events.value=eventPager.snapshot();try{const raw=await alertsRequest(alertQuery('events',{},ticket.cursor,episode.id),{current:()=>eventPager.accepts(ticket)});if(eventPager.accepts(ticket))eventPager.accept(ticket,parseAlertPage(raw,v=>parseAlertEvent(v,episode.id,episode.rule_snapshot.kind),r=>r.id))}catch(cause){eventPager.fail(ticket,cause)}finally{if(eventPager.accepts(ticket))events.value=eventPager.snapshot()}}
async function inspectRule(id:string,edit=false){resetDetails();const ticket=detailGate.ticket();detailLoading.value=true;try{const raw=await alertsRequest(`/platform/alert-rules/${alertID(id)}`,{current:()=>detailGate.accepts(ticket)});if(!detailGate.accepts(ticket))return;selectedRule.value=parseAlertEnvelope(raw,v=>parseAlertRule(v,id));if(edit){editingRule.value=selectedRule.value;editorOpen.value=true}}catch(cause){if(detailGate.accepts(ticket))detailError.value=errorText(cause)}finally{if(detailGate.accepts(ticket))detailLoading.value=false}}
async function inspectEpisode(id:string){resetDetails();const ticket=detailGate.ticket();detailLoading.value=true;try{const raw=await alertsRequest(`/platform/alerts/${alertID(id)}`,{current:()=>detailGate.accepts(ticket)});if(!detailGate.accepts(ticket))return;selectedEpisode.value=parseAlertEnvelope(raw,v=>parseAlertEpisode(v,id));eventPager.reset(context.value+':'+id);events.value=eventPager.snapshot();void loadEvents()}catch(cause){if(detailGate.accepts(ticket))detailError.value=errorText(cause)}finally{if(detailGate.accepts(ticket))detailLoading.value=false}}
function createRule(){editingRule.value=null;editorOpen.value=true}
function changed(){commandRefresh.value++;if(tab.value==='rules'){resetDetails();rulePager.reset(viewContext.value);rules.value=rulePager.snapshot();void loadRules()}else{episodePager.reset(viewContext.value);episodes.value=episodePager.snapshot();void loadEpisodes()}}
async function acknowledge(){const episode=selectedEpisode.value,actor=session.me?.user.id,csrf=session.me?.csrf_token||'';if(!episode||episode.status!=='open'||!actor||!canWrite.value||ackBusy.value||ackBlocked.value)return;const ticket=ackGate.ticket();ackBusy.value=true;ackError.value='';ackMessage.value='';try{const command=await alertCommand('acknowledge',crypto.randomUUID(),actor,{expected_action_revision:episode.action_revision},episode.id);if(!ackGate.accepts(ticket))return;const receipt=await submitAlertCommand(command,csrf,()=>ackGate.accepts(ticket));if(!ackGate.accepts(ticket)||!receipt)return;ackMessage.value=receipt.status==='applied'?'共同确认已记录。确认不会静音评估或处理资金。':alertRejectionLabels[receipt.reason]||'原操作已拒绝。';changed();if(receipt.status==='applied'){const raw=await alertsRequest(`/platform/alerts/${episode.id}`,{current:()=>ackGate.accepts(ticket)});if(ackGate.accepts(ticket)){selectedEpisode.value=parseAlertEnvelope(raw,v=>parseAlertEpisode(v,episode.id));eventPager.reset(context.value+':'+episode.id);void loadEvents()}}}catch(cause){if(ackGate.accepts(ticket))ackError.value=errorText(cause)}finally{if(ackGate.accepts(ticket)){ackBusy.value=false;commandRefresh.value++}}}
function refresh(){void loadCapabilities();resetDetails();if(tab.value==='rules')void loadRules();else void loadEpisodes()}
watch(context,()=>{capGate.reset(context.value);rulePager.reset(context.value);episodePager.reset(context.value);capabilities.value=null;capError.value='';capLoading.value=false;editorOpen.value=false;editingRule.value=null;resetDetails();rules.value=rulePager.snapshot();episodes.value=episodePager.snapshot();if(allowed.value){void loadCapabilities();if(tab.value==='rules')void loadRules();else void loadEpisodes()}},{immediate:true,flush:'sync'})
watch([tab,currentStatus,episodeKind,episodeRule],()=>{if(editorOpen.value)closeEditor();episodePager.reset(context.value+JSON.stringify([tab.value,currentStatus.value,episodeKind.value,episodeRule.value]));episodes.value=episodePager.snapshot();resetDetails();if(tab.value==='rules'){if(!rules.value.loaded)void loadRules()}else void loadEpisodes()},{flush:'sync'})
watch([ruleState,ruleKind,ruleScope],()=>{if(editorOpen.value)closeEditor();rulePager.reset(context.value+JSON.stringify([ruleState.value,ruleKind.value,ruleScope.value]));rules.value=rulePager.snapshot();resetDetails();if(tab.value==='rules')void loadRules()},{flush:'sync'})
function closeEditor(){editorOpen.value=false;editingRule.value=null;commandRefresh.value++}
function editorClosed(){if(!editorOpen.value){editingRule.value=null;commandRefresh.value++}}
onBeforeUnmount(()=>{capGate.dispose();detailGate.dispose();ackGate.dispose();rulePager.dispose();episodePager.dispose();eventPager.dispose()})
</script>
<template>
  <div class="alerts-page">
    <PageHeader eyebrow="PLATFORM OBSERVATIONS" title="经营告警" description="观察隔离、登记预算与待核对积压，在平台内共同确认并追溯每次变化。"><el-button :icon="Refresh" :loading="capLoading" @click="refresh">刷新观察</el-button><el-button v-if="admin" :icon="Plus" type="primary" :disabled="!canWrite" @click="createRule">新建规则</el-button></PageHeader>
    <el-alert v-if="!allowed" title="当前账号没有经营告警读取权限。" type="warning" :closable="false"/>
    <template v-else>
      <el-alert v-if="capError" :title="capError" type="error" :closable="false" class="alert-note"/>
      <section class="panel capability-panel"><div class="panel-body"><div class="capability-heading"><div><div class="eyebrow">EVALUATION STATUS</div><h2>{{ !capabilities?'正在核验评估能力':capabilities.reason==='available'?'站内评估已开启':capabilities.reason==='recovery_mode'?'恢复模式 · 只读观察':'评估已暂停 · 部署默认关闭' }}</h2></div><el-tag :type="capabilities?.evaluation_available?'success':'info'">{{ capabilities?.evaluation_available?'评估可用':'暂停 / 未知' }}</el-tag></div><p>{{ capabilities?.recovery_mode?'恢复期间暂停评估和写操作，仍可读取历史。':capabilities?.deployment_enabled?'目标每 60 秒观察；锁等待、容量和故障可能延迟，不保证在 60 秒内检出。':'部署开关关闭时仍可管理规则、读取历史和确认告警；不会补发历史通知。' }}</p><div class="capability-facts"><span>最多 <strong>64</strong> 条启用规则 / <strong>256</strong> 条非退役规则</span><span>成功样本超过 <strong>180 秒</strong> 显示陈旧</span><span>站内共同确认 · 无外发通知</span></div><div v-if="capabilities" class="muted small-text">服务观察时间（UTC） <time class="mono">{{ capabilities.observed_at }}</time></div></div></section>
      <el-tabs v-model="tab" class="alert-tabs"><el-tab-pane label="当前告警" name="current"/><el-tab-pane label="历史记录" name="history"/><el-tab-pane label="规则配置" name="rules"/></el-tabs>
      <section v-if="tab==='rules'" class="panel"><div class="panel-header"><div><div class="panel-title">观察规则</div><div class="panel-subtitle">种类与目标不可改；配置版本、当前样本和评估错误分别记录。列表仅表示本页。</div></div><el-button :loading="rules.loading" @click="loadRules()">读取第一页</el-button></div><div class="filters"><el-select v-model="ruleState" placeholder="全部状态" aria-label="规则状态筛选"><el-option label="全部状态" value=""/><el-option label="启用" value="enabled"/><el-option label="停用" value="disabled"/><el-option label="退役" value="retired"/></el-select><el-select v-model="ruleKind" placeholder="全部种类" aria-label="规则种类筛选"><el-option label="全部种类" value=""/><el-option v-for="k in alertKinds" :key="k" :value="k" :label="alertKindLabels[k]"/></el-select><el-input v-model="ruleScope" placeholder="目标 UUID（须选择种类）" aria-label="规则目标筛选"/></div><el-alert v-if="rules.error" :title="rules.error" type="error" :closable="false"/><el-table v-loading="rules.loading" :data="rules.rows" empty-text="当前页没有规则"><el-table-column label="规则 / 目标" min-width="290"><template #default="{row}"><strong>{{ row.label }}</strong><p class="muted small-text">{{ alertKindLabels[row.kind as keyof typeof alertKindLabels] }}</p><div class="mono muted">{{ row.scope_id }}</div></template></el-table-column><el-table-column label="状态 / 版本" min-width="140"><template #default="{row}"><el-tag>{{ stateLabel(row.state) }}</el-tag><div class="mono small-text">版本 {{ row.configuration_revision }}</div></template></el-table-column><el-table-column label="评估观察" min-width="245"><template #default="{row}"><el-tag :type="tone(row.runtime.freshness)">{{ alertFreshnessLabels[row.runtime.freshness as AlertFreshness] }}</el-tag><p v-if="row.runtime.last_error_code" class="text-warning small-text">上次评估失败：{{ row.runtime.last_error_code }}</p><div class="mono small-text">{{ row.runtime.last_success_at ?? '尚无成功样本' }}</div></template></el-table-column><el-table-column label="操作" min-width="145"><template #default="{row}"><el-button link @click="inspectRule(row.id)">详情</el-button><el-button v-if="admin&&row.state!=='retired'" link :disabled="!canWrite" @click="inspectRule(row.id,true)">配置</el-button></template></el-table-column></el-table><div class="table-footer"><span>第 {{ rules.page||1 }} 页 · 本页 {{ rules.rows.length }} 条；下一页会重新核验当前权限与观察时刻。</span><el-button :loading="rules.loading" :disabled="rules.next===null" @click="loadRules(false)">下一页</el-button></div></section>
      <section v-else class="panel"><div class="panel-header"><div><div class="panel-title">{{ tab==='history'?'已结束的发生记录':'尚未结束的发生记录' }}</div><div class="panel-subtitle">{{ tab==='history'?'每次重新触发都是新的发生记录，历史规则快照保持不变。':'确认是全平台共同记录，不停止评估、不清资金或解除隔离。' }}</div></div><el-button :loading="episodes.loading" @click="loadEpisodes()">读取第一页</el-button></div><div class="filters"><el-radio-group v-if="tab==='current'" v-model="currentStatus"><el-radio-button value="open">待确认</el-radio-button><el-radio-button value="acknowledged">已确认</el-radio-button></el-radio-group><el-select v-model="episodeKind" placeholder="全部种类" aria-label="发生记录种类筛选"><el-option label="全部种类" value=""/><el-option v-for="k in alertKinds" :key="k" :value="k" :label="alertKindLabels[k]"/></el-select><el-input v-model="episodeRule" placeholder="规则 UUID" aria-label="发生记录规则筛选"/></div><el-alert v-if="episodes.error" :title="episodes.error" type="error" :closable="false"/><el-table v-loading="episodes.loading" :data="episodes.rows" empty-text="当前页没有符合条件的发生记录"><el-table-column label="发生记录" min-width="270"><template #default="{row}"><strong>{{ row.rule_snapshot.label }}</strong><p class="muted small-text">{{ alertKindLabels[row.rule_snapshot.kind as keyof typeof alertKindLabels] }} · 第 {{ row.generation }} 次</p><div class="mono muted">{{ row.id }}</div></template></el-table-column><el-table-column label="状态" min-width="160"><template #default="{row}"><el-tag :type="row.status==='open'?'warning':row.status==='resolved'?'success':'info'">{{ stateLabel(row.status) }}</el-tag><p v-if="row.resolve_reason" class="muted small-text">{{ alertEventLabels[row.resolve_reason] }}</p><p v-if="row.acknowledged_by" class="mono small-text">确认者 {{ row.acknowledged_by }}</p></template></el-table-column><el-table-column label="发现 / 最后观察（UTC）" min-width="235"><template #default="{row}"><div class="mono small-text">{{ row.opened_at }}</div><div class="mono muted small-text">{{ row.last_seen_at }}</div></template></el-table-column><el-table-column width="95"><template #default="{row}"><el-button link @click="inspectEpisode(row.id)">详情 / 事件</el-button></template></el-table-column></el-table><div class="table-footer"><span>第 {{ episodes.page||1 }} 页 · 本页 {{ episodes.rows.length }} 条；每页独立快照。</span><el-button :loading="episodes.loading" :disabled="episodes.next===null" @click="loadEpisodes(false)">下一页</el-button></div></section>
      <el-alert v-if="detailError" :title="detailError" type="error" :closable="false" class="alert-note"/><div v-if="detailLoading" class="panel panel-body"><el-skeleton :rows="3" animated/></div>
      <section v-if="selectedRule" class="panel"><div class="panel-header"><div><div class="panel-title">{{ selectedRule.label }}</div><div class="panel-subtitle">规则当前视图 · 版本 {{ selectedRule.configuration_revision }}</div></div><el-button text @click="resetDetails">关闭详情</el-button></div><div class="panel-body"><dl class="detail-list"><dt>规则 / 目标</dt><dd class="mono">{{ selectedRule.id }}<br/>{{ selectedRule.scope_id }}</dd><dt>评估新鲜度</dt><dd><el-tag :type="tone(selectedRule.runtime.freshness)">{{ alertFreshnessLabels[selectedRule.runtime.freshness] }}</el-tag></dd><dt>上次尝试 UTC</dt><dd class="mono">{{ selectedRule.runtime.last_attempt_at ?? '尚未尝试' }}</dd><dt>下次计划 UTC</dt><dd class="mono">{{ selectedRule.runtime.next_evaluation_at ?? '无计划' }}</dd></dl><el-alert v-if="selectedRule.runtime.last_error_code" :title="`上次评估失败：${selectedRule.runtime.last_error_code}。保留此前成功样本，不代表本次已恢复。`" type="warning" :closable="false" class="alert-note"/><AlertSample :sample="selectedRule.runtime.last_sample"/><details class="snapshot"><summary>当前完整阈值参数</summary><pre>{{ JSON.stringify(selectedRule.parameters,null,2) }}</pre></details></div></section>
      <section v-if="selectedEpisode" class="panel"><div class="panel-header"><div><div class="panel-title">{{ selectedEpisode.rule_snapshot.label }} · {{ stateLabel(selectedEpisode.status) }}</div><div class="panel-subtitle">冻结规则版本 {{ selectedEpisode.rule_revision }} · 动作版本 {{ selectedEpisode.action_revision }}</div></div><el-button text @click="resetDetails">关闭详情</el-button></div><div class="panel-body"><dl class="detail-list"><dt>发生记录 / 规则</dt><dd class="mono">{{ selectedEpisode.id }}<br/>{{ selectedEpisode.rule_id }}</dd><dt>目标资源</dt><dd class="mono">{{ selectedEpisode.rule_snapshot.scope_id }}</dd><dt>规则当前新鲜度</dt><dd><el-tag :type="tone(selectedEpisode.evaluation_freshness)">{{ alertFreshnessLabels[selectedEpisode.evaluation_freshness] }}</el-tag><p class="field-hint">此状态来自规则当前评估，历史样本只代表其观察时刻。</p></dd><dt>共同确认</dt><dd><span class="mono">{{ selectedEpisode.acknowledged_by ?? '尚未确认' }}</span><br/><time class="mono">{{ selectedEpisode.acknowledged_at ?? '—' }}</time></dd><dt>结束</dt><dd>{{ selectedEpisode.resolve_reason?alertEventLabels[selectedEpisode.resolve_reason]:'尚未结束' }}<br/><time class="mono">{{ selectedEpisode.resolved_at ?? '—' }}</time></dd></dl><div class="sample-grid"><div><h3>首次发现样本</h3><AlertSample :sample="selectedEpisode.initial_sample"/></div><div><h3>最后成功观察样本</h3><AlertSample :sample="selectedEpisode.latest_sample"/></div></div><details class="snapshot"><summary>当时的完整规则快照</summary><pre>{{ JSON.stringify(selectedEpisode.rule_snapshot,null,2) }}</pre></details><div v-if="selectedEpisode.status==='open'" class="ack-area"><p>共同确认仅记录当前确认者，不静音、不结束记录，也不处理资金。</p><el-alert v-if="ackBlocked" title="此发生记录有待核查的原操作，请先只读查询原回执。" type="warning" :closable="false"/><el-button type="primary" :loading="ackBusy" :disabled="!canWrite||ackBlocked" @click="acknowledge">共同确认</el-button></div><el-alert v-if="ackError" :title="ackError" type="warning" :closable="false" class="alert-note"/><p v-if="ackMessage" class="ack-message" aria-live="polite">{{ ackMessage }}</p></div><div class="panel-header"><div class="panel-title">不可变事件历史</div><el-button :loading="events.loading" @click="loadEvents()">读取第一页</el-button></div><el-alert v-if="events.error" :title="events.error" type="error" :closable="false"/><div v-loading="events.loading" class="panel-body"><div v-for="event in events.rows" :key="event.id" class="event-row"><div class="event-heading"><strong>{{ alertEventLabels[event.type] }}</strong><span class="mono">动作版本 {{ event.action_revision }}</span></div><p class="muted small-text">{{ event.actor==='system'?'系统评估':event.actor }} · <time class="mono">{{ event.observed_at }}</time></p><AlertSample v-if="event.safe_sample" :sample="event.safe_sample"/></div><p v-if="events.loaded&&!events.rows.length" class="muted">本页没有事件。</p></div><div class="table-footer"><span>第 {{ events.page||1 }} 页 · 本页 {{ events.rows.length }} 条</span><el-button :loading="events.loading" :disabled="events.next===null" @click="loadEvents(false)">下一页事件</el-button></div></section>
      <AlertCommands :refresh="commandRefresh" :view-context="viewContext" @changed="changed"/>
    </template>
    <el-dialog v-model="editorOpen" :title="editingRule?'配置告警规则':'新建告警规则'" width="680px" destroy-on-close :close-on-click-modal="false" @closed="editorClosed"><AlertRuleEditor v-if="editorOpen" :rule="editingRule" :capabilities="capabilities" @changed="changed"/></el-dialog>
  </div>
</template>
